from PyQt5 import QtWidgets, uic


def verif(x):
    if len(x) > 0 and x.isnumeric():
        return True
    else:
        return False


def Somme():
    a = p.t1.text()
    b = p.t2.text()
    if verif(a) and verif(b):
        s = int(a) + int(b)
        p.t3.setText(str(s))
    else:
        p.t3.setText('erreur')


def Soustraction():
    a = p.t1.text()
    b = p.t2.text()
    if verif(a) and verif(b):
        s = int(a) - int(b)
        p.t3.setText(str(s))
    else:
        p.t3.setText('erreur')


def Produit():
    a = p.t1.text()
    b = p.t2.text()
    if verif(a) and verif(b):
        s = int(a) * int(b)
        p.t3.setText(str(s))
    else:
        p.t3.setText('erreur')


def division():
    a = p.t1.text()
    b = p.t2.text()
    if verif(a) and verif(b) and b != 0:
        s = int(a) / int(b)
        p.t3.setText(str(s))
    else:
        p.t3.setText('erreur')


def PGCD():
    x = p.t1.text()
    y = p.t2.text()
    if verif(x) and verif(y):
        a = abs(int(x))
        b = abs(int(y))
        if a != 0 and b != 0:
            while a != b:
                if a > b:
                    a -= b
                else:
                    b -= a
            p.t3.setText(str(a))

        else:
            p.t3.setText('Pas de PGCD')
    else:
        p.t3.setText('erreur')


def PPCM():
    x = p.t1.text()
    y = p.t2.text()
    if verif(x) and verif(y):
        a = abs(int(x))
        b = abs(int(y))
        if a != 0 and b != 0:
            sa = a
            sb = b
            while (sa != sb):
                if sa < sb:
                    sa += a
                else:
                    sb += b

            p.t3.setText(str(sa))
        else:
            p.t3.setText('Pas de PPCM')
    else:
        p.t3.setText('erreur')


app = QtWidgets.QApplication([])
p = uic.loadUi("calculatrice.ui")
p.show()
p.pb1.clicked.connect(Somme)
p.pb2.clicked.connect(Soustraction)
p.pb3.clicked.connect(Produit)
p.pb4.clicked.connect(division)
p.pb5.clicked.connect(PGCD)
p.pb6.clicked.connect(PPCM)
app.exec_()

